#!/usr/bin/env node
/**
 * The OpenSCAD parameter file, generated from data/mechanical.yaml.
 *
 * Two files that must agree about a dimension will eventually disagree about
 * it, and the failure is silent: the site says one thing, the printed part is
 * another, and nobody finds out until a board does not fit. So the numbers live
 * in one place and this writes the other.
 *
 * The generated file carries the provenance of every value as a comment, which
 * matters more here than it looks. Somebody who opens params.scad to change the
 * tube diameter should be able to see, without leaving the file, that the board
 * outline next to it is a guess.
 *
 *   node tools/gen-mechanical.mjs           write params.scad
 *   node tools/gen-mechanical.mjs --check   exit 1 if the committed file is stale
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parse } from 'yaml'

const ROOT = fileURLToPath(new URL('..', import.meta.url))
const mech = parse(readFileSync(join(ROOT, 'data/mechanical.yaml'), 'utf8'))

const OUT_DIR = join(ROOT, 'hardware/mechanical')
const OUT = join(OUT_DIR, 'params.scad')

const wrap = (text, width, indent) =>
  String(text ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .reduce((lines, word) => {
      const last = lines[lines.length - 1]
      if (last && (last + ' ' + word).length <= width) lines[lines.length - 1] = last + ' ' + word
      else lines.push(word)
      return lines
    }, [])
    .map((l) => `${indent}${l}`)
    .join('\n')

const provisional = mech.params.filter((p) => p.provenance === 'provisional')

let out = `// GENERATED by tools/gen-mechanical.mjs from data/mechanical.yaml. Do not edit.
//
// Change a dimension in data/mechanical.yaml and run \`make mech\`. Editing this
// file directly means the site and the model disagree, and the site is what a
// builder reads before ordering.
//
// ${provisional.length} of these ${mech.params.length} dimensions are provisional: not measured, not
// sourced, and they will change. They are marked PROVISIONAL below. A part
// printed from them is a fit-check, not a finished component.

`

for (const group of mech.groups) {
  const params = mech.params.filter((p) => p.group === group.id)
  if (!params.length) continue
  out += `// ${'-'.repeat(74)}\n// ${group.name.toUpperCase()}\n`
  out += `${wrap(group.note, 76, '// ')}\n\n`

  for (const p of params) {
    const tag = p.provenance === 'provisional' ? 'PROVISIONAL' : p.provenance
    out += `// ${p.what} [${tag}]\n`
    const detail = p.provenance === 'provisional' ? p.closes : p.source
    if (detail) out += `${wrap(detail, 76, '//   ')}\n`
    out += `${p.id} = ${p.value};${p.unit && p.unit !== 'count' ? `  // ${p.unit}` : ''}\n\n`
  }
}

// The one dimension that is deliberately absent, declared as undef so that a
// model asking for it fails loudly rather than silently rendering a hole at
// whatever OpenSCAD makes of an unset variable.
out += `// ${'-'.repeat(74)}
// DELIBERATELY UNSET
// The Mounting page refuses to publish a static port diameter until it has been
// derived from the enclosed volume and confirmed by flying two configurations.
// A default here would make that refusal false in the one place a builder acts
// on it, so the pod prints dimpled pilot marks at the correct positions and you
// drill them to size. Position is knowable from first principles today.
// Diameter is not.
port_dia = undef;
`

if (!existsSync(OUT_DIR)) mkdirSync(OUT_DIR, { recursive: true })

if (process.argv.includes('--check')) {
  const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : null
  if (current !== out) {
    console.error(
      'hardware/mechanical/params.scad does not match data/mechanical.yaml.\n' +
        'Run `make mech` and commit the result. The printed parts and the site are\n' +
        'currently built from different numbers.'
    )
    process.exit(1)
  }
  // The STLs are rendered locally because CI has no OpenSCAD, so what CI checks
  // instead is that nobody edited a model and forgot to re-render it. Hashing
  // the sources needs nothing but node.
  const stampPath = join(OUT_DIR, 'rendered.json')
  if (!existsSync(stampPath)) {
    console.error('hardware/mechanical/rendered.json is missing. Run `make mech`.')
    process.exit(1)
  }
  const stamp = JSON.parse(readFileSync(stampPath, 'utf8'))
  const actual = Object.fromEntries(
    readdirSync(OUT_DIR)
      .filter((f) => f.endsWith('.scad'))
      .sort()
      .map((f) => [f, createHash('sha256').update(readFileSync(join(OUT_DIR, f))).digest('hex')])
  )
  const stale = [
    ...Object.keys(actual).filter((f) => actual[f] !== stamp.sources[f]),
    ...Object.keys(stamp.sources).filter((f) => !(f in actual)),
  ]
  if (stale.length) {
    console.error(
      `The committed STLs are older than their source: ${stale.join(', ')}.\n` +
        'Run `make mech` and commit the result, or somebody downloads a model that is not\n' +
        'the one this site describes.'
    )
    process.exit(1)
  }

  console.log(
    `Mechanical parameters are current: ${mech.params.length} dimensions, ` +
      `${provisional.length} still provisional, ${Object.keys(actual).length} model sources ` +
      `matching their rendered STLs.`
  )
  process.exit(0)
}

writeFileSync(OUT, out)
console.log(
  `hardware/mechanical/params.scad: ${mech.params.length} dimensions, ` +
    `${provisional.length} provisional.`
)
